{
    "title": "locationInfo",
    "type": "object",
    "$schema": "http://json-schema.org/draft-04/schema",
    "description": "Defines how location information will be retrieved from a [CSV](csvLayer.md) file referenced through the web, ie. referenced by URL.",
    "properties": {
        "latitudeFieldName": {
            "type": "string",
            "description": "A string defining the field name that holds the latitude (Y) coordinate."
        },
        "locationType": {
            "type": "string",
            "description": "String value indicating location type.",
            "enum": [
                "coordinates"
            ]
        },
        "longitudeFieldName": {
            "type": "string",
            "description": "A string defining the field name that holds the longitude (X) coordinate."
        }
    },
    "required": [
        "locationType"
    ],
    "additionalProperties": false,
    "esriDocumentation": {
        "examples": [
            {
                "title": "locationInfo",
                "code": {
                    "locationInfo": {
                        "locationType": "coordinates",
                        "latitudeFieldName": "latitude",
                        "longitudeFieldName": "longitude"
                    }
                }
            }
        ]
    }
}

{
    "title": "lod",
    "type": "object",
    "$schema": "http://json-schema.org/draft-04/schema",
    "properties": {
        "level": {
            "type": "integer",
            "description": "ID for each level."
        },
        "levelValue": {
            "type": "string",
            "description": "String to be used when constructing URL to access a tile from this LOD."
        },
        "resolution": {
            "type": "number",
            "description": "Resolution in map units of each pixel in a tile for each level."
        },
        "scale": {
            "type": "number",
            "description": "Scale for each level."
        }
    },
    "additionalProperties": false
}

{
    "title": "Multi-dimensional Definition",
    "type": "object",
    "$schema": "http://json-schema.org/draft-04/schema",
    "properties": {
        "dimensionName": {
            "type": "string",
            "description": "Type of dimension being used (ex. StdTime)."
        },
        "isSlice": {
            "type": "boolean",
            "description": "Is slice?",
            "default": true
        },
        "values": {
            "type": "array",
            "description": "Array where every element is either a single value, or an array of two values (lower and upper bound).",
            "items": {
                "oneOf": [
                    {
                        "type": "number"
                    },
                    {
                        "type": "array",
                        "items": {
                            "type": "number"
                        },
                        "minItems": 2,
                        "maxItems": 2
                    }
                ]
            }
        },
        "variableName": {
            "type": "string",
            "description": "Name of the variable."
        }
    },
    "anyOf": [
        {
            "required": [
                "variableName"
            ]
        },
        {
            "required": [
                "dimensionName",
                "values"
            ]
        }
    ],
    "additionalProperties": false,
    "dependencies": {
        "dimensionName": [
            "values"
        ],
        "values": [
            "dimensionName"
        ]
    },
    "esriDocumentation": {
        "additionalInformation": "[Multidimensional Definition](http://resources.arcgis.com/en/help/arcgis-rest-api/index.html#//02r300000290000000) in ArcGIS REST API",
        "examples": [
            {
                "code": {
                    "multidimensionalDefinition": {
                        "variableName": "AvgSalinity",
                        "dimensionName": "StdZ",
                        "values": [
                            [
                                1406181600000,
                                1406182200000
                            ],
                            [
                                1406224800000,
                                1406225400000
                            ]
                        ],
                        "isSlice": false
                    }
                }
            }
        ]
    }
}

{
    "title": "Range",
    "$schema": "http://json-schema.org/draft-04/schema",
    "description": "Range object.",
    "properties": {
        "interactionMode": {
            "type": "string",
            "description": "Indicates the mode in which the active range should be presented to the user.",
            "enum": [
                "picker",
                "slider"
            ]
        },
        "numberOfStops": {
            "type": "number",
            "description": "This is used to generate the activeRangeValues if activeRangeValues are not specified."
        },
        "stopInterval": {
            "type": "number",
            "description": "Interval in which stops should be generated."
        }
    },
    "oneOf": [
        {
            "required": [
                "interactionMode",
                "numberOfStops"
            ]
        },
        {
            "required": [
                "interactionMode",
                "stopInterval"
            ]
        }
    ],
    "additionalProperties": false,
    "esriDocumentation": {
        "examples": [
            {
                "title": "range",
                "code": {
                    "range": {
                        "interactionMode": "slider",
                        "stopInterval": 1
                    }
                }
            }
        ]
    }
}

{
    "title": "search layer field",
    "type": "object",
    "$schema": "http://json-schema.org/draft-04/schema",
    "description": "Contains information about an attribute field in search layer configuration.",
    "properties": {
        "exactMatch": {
            "type": "boolean",
            "description": "A Boolean defining whether or not the field is an exact match."
        },
        "name": {
            "type": "string",
            "description": "A string defining the field name."
        },
        "type": {
            "type": "string",
            "description": "A string defining the field type.",
            "enum": [
                "esriFieldTypeBlob",
                "esriFieldTypeDate",
                "esriFieldTypeDouble",
                "esriFieldTypeGUID",
                "esriFieldTypeGeometry",
                "esriFieldTypeGlobalID",
                "esriFieldTypeInteger",
                "esriFieldTypeLong",
                "esriFieldTypeOID",
                "esriFieldTypeRaster",
                "esriFieldTypeSingle",
                "esriFieldTypeSmallInteger",
                "esriFieldTypeString",
                "esriFieldTypeXML"
