        },
        "type": {
            "type": "string",
            "description": "The type of the symbol",
            "enum": [
                "styleSymbolReference"
            ]
        }
    },
    "oneOf": [
        {
            "required": [
                "type",
                "name",
                "styleUrl"
            ]
        },
        {
            "required": [
                "type",
                "name",
                "styleName"
            ]
        }
    ],
    "additionalProperties": false,
    "esriDocumentation": {
        "examples": [
            {
                "code": {
                    "symbol": {
                        "type": "styleSymbolReference",
                        "styleName": "EsriThematicTreesStyle",
                        "name": "Frangula"
